-- ============================================
-- LUMA — Thème 14 : LONG 2/3 x4 — Une amitié qui se noue en chemin
-- ============================================


update scenarios set content = '{"characters": {"sam": "Sam", "traveler": "le voyageur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "traveler", "text": "Mind if I ask — heading the same direction? My car broke down back there.", "text_fr": "Ça vous dérange si je demande — vous allez dans la même direction ? Ma voiture est tombée en panne là-bas.", "choices": [{"text": "I am, actually. Need a lift to the next town?", "text_fr": "En fait oui. Besoin d''un lift jusqu''à la prochaine ville ?", "next": "n2"}, {"text": "Yeah, heading west. What happened with your car?", "text_fr": "Ouais, je vais vers l''ouest. Qu''est-ce qui s''est passé avec votre voiture ?", "next": "n2b"}]}, "n2": {"speaker": "traveler", "text": "That would be amazing, thank you so much. I''m Sam, by the way.", "text_fr": "Ce serait incroyable, merci beaucoup. Je m''appelle Sam, au fait.", "choices": [{"text": "Nice to meet you, Sam. Hop in, I''m happy to help.", "text_fr": "Ravi de te rencontrer, Sam. Monte, je suis content d''aider.", "next": "n3"}]}, "n2b": {"speaker": "traveler", "text": "Engine trouble, sadly. Tow truck''s coming for it, but I need to get to the next town.", "text_fr": "Problème de moteur, malheureusement. La dépanneuse arrive pour elle, mais je dois arriver à la prochaine ville.", "choices": [{"text": "I can give you a lift there, no problem at all.", "text_fr": "Je peux te déposer là-bas, aucun problème.", "next": "n3"}]}, "n3": {"speaker": "sam", "text": "I really appreciate this. Road trip solo, or is someone else with you?", "text_fr": "J''apprécie vraiment ça. Road trip solo, ou quelqu''un d''autre est avec toi ?", "choices": [{"text": "Solo actually, needed some time to think and explore.", "text_fr": "Solo en fait, j''avais besoin de temps pour réfléchir et explorer.", "next": "n4"}, {"text": "With a friend, they''re actually napping in the back seat.", "text_fr": "Avec un ami, il/elle fait justement la sieste sur la banquette arrière.", "next": "n4"}]}, "n4": {"speaker": "sam", "text": "That sounds nice, solo trips have a special kind of freedom to them.", "text_fr": "Ça a l''air sympa, les voyages solo ont une liberté particulière.", "choices": [{"text": "They really do. What about you, where are you headed overall?", "text_fr": "C''est vrai. Et toi, tu vas où au final ?", "next": "n5"}]}, "n5": {"speaker": "sam", "text": "Honestly, just following the road wherever it leads. No fixed plan.", "text_fr": "Honnêtement, je suis juste la route où qu''elle mène. Pas de plan fixe.", "choices": [{"text": "That''s a really freeing way to travel, honestly.", "text_fr": "C''est une façon vraiment libératrice de voyager, honnêtement.", "next": "n6"}]}, "n6": {"speaker": "sam", "text": "It is! Say, would you mind if I tagged along for a bit longer, once my car''s sorted?", "text_fr": "C''est le cas ! Dis, ça te dérangerait si je t''accompagnais encore un peu, une fois ma voiture réglée ?", "choices": [{"text": "I''d actually really enjoy the company, honestly.", "text_fr": "J''apprécierais vraiment la compagnie, honnêtement.", "next": "n7"}, {"text": "Sure, as long as our routes still align.", "text_fr": "Bien sûr, tant que nos itinéraires s''alignent toujours.", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(Over the next few days, you and Sam explore several towns together, swapping stories.)", "text_fr": "(Au cours des jours suivants, toi et Sam explorez plusieurs villes ensemble, en échangeant des histoires.)", "choices": [{"text": "(Share a favorite memory from your own life with Sam.)", "text_fr": "(Partage un souvenir préféré de ta propre vie avec Sam.)", "next": "n8"}]}, "n8": {"speaker": "sam", "text": "You know, this chance meeting turned into one of the best parts of my trip.", "text_fr": "Tu sais, cette rencontre fortuite est devenue l''une des meilleures parties de mon voyage.", "choices": [{"text": "Same here, honestly. I wasn''t expecting to make a real friend on the road.", "text_fr": "Pareil pour moi, honnêtement. Je m''attendais pas à me faire un vrai ami sur la route.", "next": "n9"}]}, "n9": {"speaker": "sam", "text": "Life''s funny that way. My car breaking down turned into meeting you.", "text_fr": "La vie est marrante comme ça. Ma voiture qui tombe en panne s''est transformée en te rencontrer.", "choices": [{"text": "Silver linings, I guess. Let''s make the most of the rest of this trip.", "text_fr": "Un bon côté aux choses, je suppose. Profitons au maximum du reste de ce voyage.", "next": "n10"}]}, "n10": {"speaker": "sam", "text": "(As your routes finally diverge) This is where we part ways, I think.", "text_fr": "(Alors que vos itinéraires divergent enfin) C''est ici qu''on se sépare, je pense.", "choices": [{"text": "It''s been an unexpected but really special part of this trip. Let''s stay in touch.", "text_fr": "Ça a été une partie inattendue mais vraiment spéciale de ce voyage. Restons en contact.", "next": "end_friendship"}]}, "end_friendship": {"speaker": "sam", "text": "Definitely. Thank you for the ride, the stories, and honestly, the friendship.", "text_fr": "Définitivement. Merci pour le trajet, les histoires, et honnêtement, l''amitié.", "end": true, "ending_label": "Une amitié précieuse née d''une panne de voiture 🚗🤝"}}}'::jsonb, is_playable = true
where title = 'Une amitié qui se noue en chemin'
  and theme_id = (select id from scenario_themes where position = 14 and language_id = (select id from languages where code = 'en'));
